s/const FLEE_RATIO = 0.4;/const FLEE_RANGE = 0.09;
const FLEE_TIME = 1.2;/;
s/  wander: number;
  flash: number;
  eaten/  wander: number;
  flee: number;
  flash: number;
  eaten/;
s/    wander: w.rng\(\) \* Math.PI \* 2,
    flash: 0,/    wander: w.rng() * Math.PI * 2,
    flee: 0,
    flash: 0,/;
s/    wander: w.rng\(\) \* Math.PI \* 2,
    flash: 1,/    wander: w.rng() * Math.PI * 2,
    flee: 0,
    flash: 1,/;
s/  const fleeR = vis \* FLEE_RATIO;
/  const fleeR = FLEE_RANGE * R;
  if (nrD2 < fleeR * fleeR) b.flee = FLEE_TIME;
/;
s/  if \(nrD2 < fleeR \* fleeR\) \{
    const d = Math.sqrt\(nrD2\) \|\| 1e-6;/  if (b.flee > 0) {
    b.flee = Math.max(0, b.flee - dt);
    const d = Math.sqrt(nrD2) || 1e-6;/;
' src/sim.ts

