args.command:
cd /private/var/folders/7z/5mtgxwxx4zs9ppgzm942gbmh0000gn/T/workspace.Fo57nx/app && sed -i '' "s/const BLUE_LOSS_RATIO = [0-9.]*;/const BLUE_LOSS_RATIO = 0.5;/" src/sim.ts && cat > scripts/_search.ts <<'EOF'
import { DEFAULTS } from "../src/settings.ts";
import { createWorld, step, snapshot, SIM_DT } from "../src/sim.ts";
const grid: Record<string, number[]> = {
  blueCopy: [78, 88],
  redCopy: [75, 90],
  redContact: [3, 6, 10],
  redUse: [0.4, 0.8],
  blueUse: [0.9, 1.2],
  fruitGrowth: [0.12, 0.2],
};
const keys = Object.keys(grid);
const combos: Record<string, number>[] = [{}];
for (const k of keys) {
  const next: Record<string, number>[] = [];
  for (const c of combos) for (const v of grid[k]) next.push({ ...c, [k]: v });
  combos.splice(0, combos.length, ...next);
}
const results: { ov: Record<string, number>; score: number; info: string }[] = [];
for (const ov of combos) {
  let score = 0;
  const infos: string[] = [];
  for (const seed of [1, 2]) {
    const w = createWorld({ ...DEFAULTS, ...ov, redPause: 3, fruitDelay: 2, seed });
    const series = [];
    for (let i = 0; i < 1500 / SIM_DT; i++) {
      step(w, SIM_DT);
      if (i % 200 === 0) series.push(snapshot(w));
    }
    const late = series.filter((s) => s.t >= 500).map((s) => s.blue);
    const lateR = series.filter((s) => s.t >= 500).map((s) => s.red);
    const minB = Math.min(...late), minR = Math.min(...lateR);
    let peaks = 0;
    for (let i = 1; i < late.length - 1; i++) if (late[i] > late[i - 1] && late[i] >= late[i + 1] && late[i] - Math.min(...late.slice(Math.max(0, i - 5), i)) > 4) peaks++;
    const alive = minB > 0 && minR > 0 ? 1 : 0;
    score += alive * (peaks + Math.min(minB, 10) / 10);
    infos.push(`s${seed}: B ${minB}-${Math.max(...late)} R ${minR}-${Math.max(...lateR)} pk${peaks}`);
  }
  results.push({ ov, score, info: infos.join(" | ") });
}
results.sort((a, b) => b.score - a.score);
for (const r of results.slice(0, 8)) console.log(JSON.stringify(r.ov), r.score.toFixed(1), r.info);
EOF
time node --experimental-strip-types scripts/_search.ts

