args.command:
cd /private/var/folders/7z/5mtgxwxx4zs9ppgzm942gbmh0000gn/T/workspace.Fo57nx/app && cat > scripts/_cand.ts <<'EOF'
import { DEFAULTS } from "../src/settings.ts";
import { createWorld, step, snapshot, SIM_DT } from "../src/sim.ts";
const cands: Record<string, unknown>[] = JSON.parse(process.env.CANDS ?? "[]");
for (const ov of cands) {
  const out: string[] = [];
  for (const seed of [1, 2]) {
    const w = createWorld({ ...DEFAULTS, ...ov, seed } as typeof DEFAULTS);
    const ser = [];
    for (let i = 0; i < 1200 / SIM_DT; i++) { step(w, SIM_DT); if (i % 100 === 0) ser.push(snapshot(w)); }
    const late = ser.filter((s) => s.t >= 400);
    const rng = (k: "blue" | "red" | "fruit") => `${Math.min(...late.map((s) => s[k]))}-${Math.max(...late.map((s) => s[k]))}`;
    const end = ser[ser.length - 1];
    out.push(`s${seed} B[${rng("blue")}] R[${rng("red")}] F[${rng("fruit")}] end B${end.blue}/R${end.red}`);
  }
  console.log(JSON.stringify(ov), "\n   ", out.join(" | "));
}
EOF
