  private proj(nx: number, ny: number, nz: number): { sx: number; sy: number } {
    const c = Math.cos(this.yaw);
    const s = Math.sin(this.yaw);
    const rx = nx * c - ny * s;
    const ry = nx * s + ny * c;
    const b = this.base();
