    // Soft shadow on the table.
    ctx.save();
    ctx.fillStyle = "rgba(90,50,20,0.18)";
    ctx.beginPath();
    ctx.ellipse(center.sx + b * 0.03, center.sy + b * 0.08, b * 1.12, b * 0.62 * TILT * 1.9, 0, 0, Math.PI * 2);
