    g.addColorStop(0.45, pal.mid);
    g.addColorStop(1, pal.lo);
    ctx.fillStyle = g;
    ctx.fill();
    ctx.lineWidth = Math.max(1, rx * 0.07);
    ctx.strokeStyle = pal.ink;
    ctx.stroke();

    // Gloss.
    ctx.fillStyle = "rgba(255,255,255,0.7)";
    ctx.beginPath();
