    ctx.beginPath();
    ctx.moveTo(X(ev.t) - 4, m.t - 10);
    ctx.lineTo(X(ev.t) + 4, m.t - 10);
    ctx.lineTo(X(ev.t), m.t - 3);
    ctx.closePath();
    ctx.fill();
  }

