import { DEFAULTS } from "../src/settings.ts";
import { createWorld, step, snapshot, SIM_DT } from "../src/sim.ts";
const grid: Record<string, number[]> = { redCopy: [80, 88], redUse: [0.9, 1.0], redContact: [2, 2.5], redPause: [1.5, 2.2], blueCopy: [70, 78] };
let combos: Record<string, number>[] = [{}];
for (const k of Object.keys(grid)) combos = combos.flatMap((c) => grid[k].map((v) => ({ ...c, [k]: v })));
const crossings = (a: number[]) => { const m = a.reduce((x, y) => x + y, 0) / a.length; let n = 0; for (let i = 1; i < a.length; i++) if ((a[i] - m) * (a[i - 1] - m) < 0) n++; return n; };
const rows: string[] = [];
for (const ov of combos) {
  let worst = 1e9; const parts: string[] = [];
  for (const seed of [1, 2, 3, 4]) {
    const w = createWorld({ ...DEFAULTS, ...ov, seed });
    const B: number[] = [], R: number[] = [];
    for (let i = 0; i < 2400 / SIM_DT; i++) { step(w, SIM_DT); if (i % 100 === 0) { const s = snapshot(w); if (s.t > 600) { B.push(s.blue); R.push(s.red); } } }
    const alive = Math.min(...B) > 0 && Math.min(...R) > 0;
    const cyc = alive ? Math.min(crossings(B), crossings(R)) / 2 : 0;
    worst = Math.min(worst, cyc);
    parts.push(`${cyc.toFixed(0)}`);
  }
  rows.push(`${worst.toFixed(1)}  ${JSON.stringify(ov)}  cycles=[${parts.join(",")}]`);
}
rows.sort((a, b) => parseFloat(b) - parseFloat(a));
console.log(rows.slice(0, 8).join("\n"));
EOF
time node --experimental-strip-types .verify/tune.ts

